  "understanding": {
    "purpose": "Document validation rules, valid examples, and error messages for customer onboarding fields.",
    "reading": "Readers locate a field, then read across its row to compare the rule with a valid example and the message shown when validation fails. Long pattern rows can absorb some natural wrapping in the example and message columns.",
    "groups": [
      "Field and Pattern identify what is validated and define the rule.",
      "Example valid and Error message show the rule's practical outcomes and should be easy to compare with it."
    ],
    "keep_intact": [
      "Field names, so rows remain easy to locate.",
      "Regex tokens and expressions where possible, because inserted line breaks make syntax harder to follow.",
      "Example values and identifiers, because their exact characters matter."
    ],
    "may_wrap": [
      "Error messages at word boundaries.",
      "Long patterns across lines when necessary, with enough width to limit fragmentation.",
      "Multiword examples at natural spaces where their meaning remains clear."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [147, 135, 188, 178],
      "idea": "Preserve the longest unbreakable content in each column while showing the beginning of examples in the initial viewport, accepting substantial pattern wrapping and horizontal scrolling."
    },
    {
      "name": "B",
      "widths": [147, 180, 188, 220],
      "idea": "Give patterns and messages more room to reduce wrapping, while leaving a narrow glimpse of the example column at the viewport edge."
    },
    {
      "name": "C",
      "widths": [147, 300, 188, 250],
      "idea": "Prioritize reading and comparing regexes with fewer breaks, accepting that the initial viewport ends within the pattern column and the remaining columns require more scrolling."
    }
  ]
}
